class vector3d {
public:
  typedef float T;
  T x, y, z;
  inline vector3d() {}
  inline vector3d(T _x, T _y, T _z) { x = _x; y = _y; z = _z; }
  inline T length() const { return (T)__fsqrt(x*x + y*y + z*z); }
};
inline vector3d operator-(const vector3d& a, const vector3d& b)
